begin;do $$declare quiz uuid;question uuid;begin select id into quiz from public.quizzes where slug='general-waste-foundation' and version=1; if not exists(select 1 from public.quiz_questions where quiz_id=quiz and position=3) and not exists(select 1 from public.quiz_attempts where quiz_id=quiz) then insert into public.quiz_questions(quiz_id,position,prompt,choices) values(quiz,3,'ถ่านไฟฉายใช้แล้วควรทำอย่างไร?','["เผา", "เจาะก่อนทิ้ง", "แยกส่งจุดรับของเสียอันตราย"]'::jsonb) returning id into question;insert into private.quiz_answer_keys(question_id,answer,explanation) values(question,2,'ไม่แกะ เจาะ หรือเผา และใช้จุดรับที่เหมาะสม');end if;end;$$;commit;